@@ -1,3 +1,11 @@
 import { READ_COLUMNS } from "./schema.ts";

-export const select = (): string => `select ${READ_COLUMNS.join(", ")} from orders`;
+export const select = (): string => {
+  const columns = READ_COLUMNS.map(col => {
+    if (col === "currency") {
+      return `COALESCE(${col}, 'USD') as ${col}`;
+    }
+    return col;
+  }).join(", ");
+  return `select ${columns} from orders`;
+};
